import functools
from time import time

from ute_admin_infomodel.exception import InfoModelQueryTimeoutException
from ute_admin_infomodel.parsing.converter import convert_value, convert_dist_name

from .parser import InfoModelQueryParser, InfoModelPredicateParser, InfoModelConditionParser
from .util import filter_im_dump, check_object, count_objects, get_comparator_function


class QueryResult(object):

    def __init__(self, value, message=''):
        self.value = value
        self.message = message

    def __nonzero__(self):
        return bool(self.value)

    def __bool__(self):
        return bool(self.value)

    def __len__(self):
        return len(self.value)

    def __str__(self):
        return str(self.value) if self else self.message


class PositiveQueryResult(QueryResult):

    def __init__(self, value=True):
        QueryResult.__init__(self, value)

    def __nonzero__(self):
        return True

    def __bool__(self):
        return True


class NegavtiveQueryResult(QueryResult):

    def __init__(self, message):
        QueryResult.__init__(self, False, message)


class Query(object):

    def __init__(self, query_expression):
        self.expression = query_expression

        parsed_query = InfoModelQueryParser().parse(query_expression)

        self.function = self._get_function(parsed_query)
        self.predicates = self._get_predicates(parsed_query)
        self.dist_name_regex = self._get_dist_name_regex(parsed_query)

        if self.function == 'count':
            self.condition_operator, self.condition_value = self._get_condition(parsed_query)

    def _get_function(self, parsed_query):
        return getattr(parsed_query, 'function') or 'check'

    def _get_dist_name_regex(self, parsed_query):
        return convert_dist_name(parsed_query.dist_name)

    def _get_predicates(self, parsed_query):
        predicates_list = parsed_query.predicates_joined
        result = []
        for pred in predicates_list:
            parsed_predicate = InfoModelPredicateParser().parse(pred)
            parsed_predicate_value = parsed_predicate.value if parsed_predicate.quoted else convert_value(parsed_predicate.value)
            result.append((parsed_predicate.name, parsed_predicate.symbol, parsed_predicate_value))
        return tuple(result)

    def _get_condition(self, parsed_query):
        parsed_condition = InfoModelConditionParser().parse(" ".join(parsed_query.condition.asList()))
        return parsed_condition.symbol, int(parsed_condition.value)


def get_dump_dict_objects(method=None, fail_on_empty=False):
    """Get filtered objects from Infomodel dump and pass it to decorated function."""
    if method is None:
        return functools.partial(get_dump_dict_objects, fail_on_empty=fail_on_empty)

    @functools.wraps(method)
    def _wrap(self, query, timeout):
        dump_dict_objects = filter_im_dump(self.im_provider.get_infomodel_dump(timeout), query.dist_name_regex)
        if fail_on_empty and not dump_dict_objects:
            return NegavtiveQueryResult('Not found any object matching given dist name.')
        return method(self, query, dump_dict_objects)

    return _wrap


class QueryModel(object):

    def __init__(self, im_provider, allow_negative_result):
        self.im_provider = im_provider
        self.allow_negative_result = allow_negative_result

        self.query_functions = {
            'check': self._check_any_object,
            'every': self._check_every_object,
            'count': self._check_objects_count,
            'get list': self._get_filtered_objects_list,
            'get count': self._get_objects_count,
            'get object': self._get_selected_object,
            'none': self._check_none_object
        }

    def query_infomodel(self, query_expression, timeout):
        """Query InfoModel"""
        query = Query(query_expression)
        query_function = self.query_functions[query.function]
        result = None
        time_left = timeout
        start_time, end_time = time(), time()
        while not result:
            start_time = time()
            result = query_function(query, time_left)
            end_time = time()
            time_left = time_left - (end_time - start_time)
            if not result and time_left < 0.0:
                if self.allow_negative_result:
                    break
                else:
                    raise InfoModelQueryTimeoutException(
                        "Query: '%s' doesn't pass in timeout=%s. %s" % (query_expression, timeout, result.message))

        return result.value, start_time, end_time, query_expression

    @get_dump_dict_objects(fail_on_empty=True)
    def _check_every_object(self, query, dump_dict_objects):
        for dist_name, dump_object in dump_dict_objects:
            if not check_object(dump_object, query.predicates):
                return NegavtiveQueryResult('Object does not match given predicates.\n{} : {}'.format(dist_name, dump_object))
        return PositiveQueryResult()

    @get_dump_dict_objects(fail_on_empty=True)
    def _check_any_object(self, query, dump_dict_objects):
        for dist_name, dump_dict_object in dump_dict_objects:
            if check_object(dump_dict_object, query.predicates):
                return PositiveQueryResult()
        return NegavtiveQueryResult('Found objects do not match given predicates.\n{}'.format(dump_dict_objects))

    @get_dump_dict_objects(fail_on_empty=False)
    def _check_none_object(self, query, dump_dict_objects):
        for dist_name, dump_object in dump_dict_objects:
            if check_object(dump_object, query.predicates):
                return NegavtiveQueryResult('Found objects matching given predicates.\n{}'.format(dump_dict_objects))
        return PositiveQueryResult()

    @get_dump_dict_objects
    def _get_filtered_objects_list(self, query, dump_dict_objects):
        object_list = [
            (dist_name, dump_dict_object) for dist_name, dump_dict_object in dump_dict_objects if check_object(dump_dict_object, query.predicates)]
        return QueryResult(object_list, 'Matching objects not found.')

    @get_dump_dict_objects
    def _get_selected_object(self, query, dump_dict_objects):
        object_list = [
            (dist_name, dump_dict_object) for dist_name, dump_dict_object in dump_dict_objects if check_object(dump_dict_object, query.predicates)]
        if len(object_list) == 1:
            return QueryResult(object_list[0])
        return QueryResult(None, 'Query is ambigiuos. Too many matching objects found.' if object_list else 'Matching object not found.')

    @get_dump_dict_objects
    def _check_objects_count(self, query, dump_dict_objects):
        count = count_objects(dump_dict_objects, query.predicates)
        compare = get_comparator_function(query.condition_operator)
        return QueryResult(compare(count, query.condition_value), 'Actual count = {}'.format(count))

    @get_dump_dict_objects
    def _get_objects_count(self, query, dump_dict_objects):
        count = count_objects(dump_dict_objects, query.predicates)
        return PositiveQueryResult(count)
